css:
.rows {
  max-width: 280px;
  margin: 16px;
  padding: 0;
  list-style: none;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  overflow: hidden;
  font-family: system-ui, sans-serif;
}

.item {
  padding: 8px 14px;
  cursor: pointer;
}

.item:nth-child(even) {
  background-color: #fff7ed;
}

.item:hover {
  background-color: #fed7aa;
}
